package edu.gcu.cst339.lab2_chinook_api.mediatype;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * Data transfer object used as the JSON request and response body for media types.
 *
 * @param mediaTypeId the media type ID; generated by the database, so it is
 *                    ignored on create and taken from the URL on update
 * @param name        the media type name; required, at most 120 characters
 */
public record MediaTypeDto(
        Integer mediaTypeId,
        @NotBlank
        @Size(max = 120)
        String name
) {
    /**
     * Converts a media type entity into a DTO.
     *
     * @param mediaType the entity to convert
     * @return a DTO containing the entity's ID and name
     */
    static MediaTypeDto fromEntity(MediaType mediaType) {
        return new MediaTypeDto(mediaType.getMediaTypeId(), mediaType.getName());
    }
}